-- 只在 ktd_lx 执行，最后必须 ROLLBACK；结果仅保留调查必要字段。
SET SESSION MAX_EXECUTION_TIME=20000;
SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SET SESSION TRANSACTION READ ONLY;
START TRANSACTION WITH CONSISTENT SNAPSHOT, READ ONLY;
SELECT DATABASE() db,@@hostname server_host,@@port server_port,NOW() snapshot_time,@@session.time_zone time_zone,@@session.transaction_read_only read_only,@@session.max_execution_time max_execution_time;
SELECT w.id,w.event_id,e.event_no,w.step_type,w.step_type_name,w.occurred_time,w.create_time,w.del_flag+0 deleted FROM bo_event_work_order w LEFT JOIN bo_task_event e ON e.id=w.event_id WHERE w.occurred_time BETWEEN '2026-10-10 10:50:00' AND '2026-10-10 11:10:00' ORDER BY w.occurred_time,w.id;
SELECT e.id,e.event_no,e.project_id,e.recheck_status,e.recheck_time,e.update_time,e.del_flag+0 deleted,CASE WHEN JSON_VALID(e.imgxy) THEN JSON_LENGTH(e.imgxy) END event_box_count,SHA2(e.recheck_result,256) result_sha256,SHA2(e.imgxy,256) input_sha256,CHAR_LENGTH(e.recheck_result) result_length FROM bo_task_event e WHERE e.recheck_time BETWEEN '2026-10-10 10:50:00' AND '2026-10-10 11:10:00' OR EXISTS (SELECT 1 FROM bo_event_work_order w WHERE w.event_id=e.id AND w.occurred_time BETWEEN '2026-10-10 10:50:00' AND '2026-10-10 11:10:00') ORDER BY e.recheck_time,e.id;
SELECT r.id,r.event_id,r.annex_id,r.file_name,r.session_id,r.total,r.true_count,r.false_count,r.doubtful_count,r.recheck_time,r.create_time,r.update_time,r.del_flag+0 deleted FROM bo_task_event_image_recheck_result r WHERE r.recheck_time BETWEEN '2026-10-10 10:50:00' AND '2026-10-10 11:10:00' OR EXISTS (SELECT 1 FROM bo_event_work_order w WHERE w.event_id COLLATE utf8mb4_general_ci=r.event_id COLLATE utf8mb4_general_ci AND w.occurred_time BETWEEN '2026-10-10 10:50:00' AND '2026-10-10 11:10:00') ORDER BY r.recheck_time,r.id;
SELECT a.id,a.busi_id,a.event_id,a.file_name,a.busi_type_code,a.file_type,a.del_flag+0 deleted,a.create_time,a.update_time,CASE WHEN JSON_VALID(a.imgxy) THEN JSON_LENGTH(a.imgxy) END annex_box_count,SHA2(a.imgxy,256) input_sha256 FROM sys_annex_file a WHERE a.busi_id IN (SELECT w.event_id FROM bo_event_work_order w WHERE w.step_type_name='提交慧眼复核' AND w.occurred_time BETWEEN '2026-10-10 10:50:00' AND '2026-10-10 11:10:00') ORDER BY a.busi_id,a.id;
SELECT id,event_id,step_type_name,occurred_time,features,remark,del_flag+0 deleted FROM bo_event_work_order WHERE step_type_name LIKE '%复核%' AND event_id IN (SELECT x.event_id FROM (SELECT DISTINCT event_id FROM bo_event_work_order WHERE step_type_name='提交慧眼复核' AND occurred_time BETWEEN '2026-10-10 10:50:00' AND '2026-10-10 11:10:00') x) ORDER BY occurred_time,id;
ROLLBACK;
